"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96643"],{88878(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_obrigatoria","status":422,"titulo":"A classifica\xe7\xe3o baseada em ENEM com c\xe1lculo local exige a resolu\xe7\xe3o de Pesos por \xc1rea"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_obrigatoria","requisitos":[],"oQueAconteceu":["A classifica\xe7\xe3o est\xe1 marcada como baseada em ENEM (`baseadoEmEnem: true`) com c\xe1lculo local\\npela m\xe9dia ponderada (`FORMULA_MEDIA_PONDERADA`), mas n\xe3o trouxe `resolucaoPesoAreaEnem`, ou\\ntrouxe o campo s\xf3 com espa\xe7os. Essa \xe9 a \xfanica combina\xe7\xe3o que calcula a nota pelos pesos por\\n\xe1rea do ENEM, e por isso a \xfanica que exige a resolu\xe7\xe3o: \xe9 por ela que o sistema busca, no\\ncadastro de Pesos por \xc1rea (Configura\xe7\xe3o), o peso e o corte de cada \xe1rea de cada grupo, e\\ncongela uma c\xf3pia deles na classifica\xe7\xe3o.","A recusa vem no campo `resolucaoPesoAreaEnem` e acumula, na mesma resposta, com as demais\\nviola\xe7\xf5es da classifica\xe7\xe3o. Sem a resolu\xe7\xe3o, o cadastro n\xe3o \xe9 consultado.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o da classifica\xe7\xe3o, conforme a causa:","- **O processo calcula a nota pelos pesos por \xe1rea do ENEM:** informe, em\\n  `resolucaoPesoAreaEnem`, a resolu\xe7\xe3o cadastrada em Pesos por \xc1rea que o edital adota.\\n- **O processo n\xe3o calcula a nota pelos pesos por \xe1rea do ENEM:** a classifica\xe7\xe3o n\xe3o deve\\n  estar marcada como baseada em ENEM com m\xe9dia ponderada. Nas demais combina\xe7\xf5es a resolu\xe7\xe3o\\n  n\xe3o se aplica; ver\\n  [`resolucao_peso_area_enem_indevida`](/erros/uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_indevida).","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);